<?php $page_title='Dashboard';require_once __DIR__.'/includes/header.php';
$patients=$pdo->query("SELECT COUNT(*) c FROM patients")->fetch()['c'];$doctors=$pdo->query("SELECT COUNT(*) c FROM doctors")->fetch()['c'];$apps=$pdo->query("SELECT COUNT(*) c FROM appointments WHERE appointment_date>=CURDATE() AND status<>'cancelled'")->fetch()['c'];$revenue=$pdo->query("SELECT COALESCE(SUM(amount),0)c FROM bills WHERE status='paid'")->fetch()['c'];
$today=$pdo->query("SELECT a.*,p.name patient,d.name doctor FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id WHERE a.appointment_date=CURDATE() ORDER BY a.appointment_time")->fetchAll();?>
<div class="hero mb-4"><h1>Clinic Dashboard</h1><p class="mb-0">Manage patients, doctors, appointments, medical records and billing.</p></div>
<div class="row g-3 mb-4"><?php foreach([['Patients',$patients,'bi-people'],['Doctors',$doctors,'bi-person-badge'],['Upcoming Appointments',$apps,'bi-calendar-check'],['Paid Revenue','$'.number_format($revenue,2),'bi-cash-stack']] as $x):?><div class="col-md-6 col-xl-3"><div class="card p-4"><div class="text-muted"><?=$x[0]?></div><div class="stat"><?=$x[1]?></div><i class="bi <?=$x[2]?> fs-4 text-primary"></i></div></div><?php endforeach;?></div>
<div class="card p-4"><div class="d-flex justify-content-between mb-3"><h5>Today's Appointments</h5><a href="appointments/add.php" class="btn btn-primary btn-sm">+ Appointment</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Time</th><th>Patient</th><th>Doctor</th><th>Reason</th><th>Status</th></tr></thead><tbody><?php foreach($today as $a):?><tr><td><?=$a['appointment_time']?></td><td><?=e($a['patient'])?></td><td><?=e($a['doctor'])?></td><td><?=e($a['reason'])?></td><td><span class="badge text-bg-info"><?=$a['status']?></span></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require_once __DIR__.'/includes/footer.php';?>